import {ART_TOOLS,StrokeSampler,brushRadius,brushMask} from './art-brushes.js';
export const ART_WIDTH=720,ART_HEIGHT=440,ART_HISTORY_BYTES=16*1024*1024;
const W=ART_WIDTH,H=ART_HEIGHT,T=64,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),valid=p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y),point=p=>({x:clamp(p.x,0,W-1),y:clamp(p.y,0,H-1),pressure:Number.isFinite(p.pressure)?clamp(p.pressure,0,1):.5});
const rgb=s=>/^#[0-9a-f]{6}$/i.test(s??'')?[1,3,5].map(i=>parseInt(s.slice(i,i+2),16)):[45,61,67];
export class ArtDocument{
 constructor({onChange=()=>{}}={}){this.ink=new Uint8ClampedArray(W*H*4);this.mask=new Uint8ClampedArray(W*H);this.output=new Uint8ClampedArray(W*H*4);this.paperColor='#fff7df';this.undoStack=[];this.redoStack=[];this.active=null;this.epoch=0;this.seed=0;this.onChange=onChange;}
 get historyBytes(){return [...this.undoStack,...this.redoStack].reduce((s,a)=>s+a.bytes,0);}get historyCount(){return this.undoStack.length+this.redoStack.length;}get canUndo(){return this.undoStack.length>0;}get canRedo(){return this.redoStack.length>0;}
 changed(){this.epoch++;this.onChange(this);}
 tile(key){const x=key%12*T,y=Math.floor(key/12)*T,w=Math.min(T,W-x),h=Math.min(T,H-y),data=new Uint8ClampedArray(w*h*4);for(let j=0;j<h;j++)data.set(this.ink.subarray(((y+j)*W+x)*4,((y+j)*W+x+w)*4),j*w*4);return {x,y,w,h,data};}
 touch(x0,y0,x1,y1){for(let y=Math.floor(clamp(y0,0,H-1)/T);y<=Math.floor(clamp(y1,0,H-1)/T);y++)for(let x=Math.floor(clamp(x0,0,W-1)/T);x<=Math.floor(clamp(x1,0,W-1)/T);x++){const key=y*12+x;if(!this.active.before.has(key))this.active.before.set(key,this.tile(key));}}
 begin(options,p){if(!valid(p))return false;this.end();const tool=ART_TOOLS[options.tool]?options.tool:'pencil',def=ART_TOOLS[tool];this.redoStack=[];this.mask.fill(0);this.active={tool,size:clamp(Number(options.size)||def.size,def.min,def.max),color:rgb(options.color),opacity:clamp(Number.isFinite(options.opacity)?options.opacity:1,.1,1),seed:options.seed??++this.seed,before:new Map()};this.active.sampler=new StrokeSampler(point(p),Math.max(.7,this.active.size*.13),p=>this.dab(p));this.changed();return true;}
 dab(p){const a=this.active,r=brushRadius(a.tool,a.size,p.pressure),x0=Math.max(0,Math.floor(p.x-r)),x1=Math.min(W-1,Math.ceil(p.x+r)),y0=Math.max(0,Math.floor(p.y-r)),y1=Math.min(H-1,Math.ceil(p.y+r));this.touch(x0,y0,x1,y1);for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const i=y*W+x,v=Math.round(255*brushMask(a.tool,x,y,p.x,p.y,r,a.seed));if(v>this.mask[i])this.mask[i]=v;}}
 move(p){if(!this.active||!valid(p))return;this.active.sampler.move(point(p));this.changed();}
 mix(i,out,j=i){const a=this.active,m=a?this.mask[i/4]/255*a.opacity:0,d=this.ink[i+3]/255;if(a?.tool==='eraser'){out[j]=this.ink[i];out[j+1]=this.ink[i+1];out[j+2]=this.ink[i+2];out[j+3]=Math.round(255*d*(1-m));return;}const alpha=m+d*(1-m);for(let k=0;k<3;k++)out[j+k]=alpha?(m*(a?.color[k]??0)+d*(1-m)*this.ink[i+k])/alpha:0;out[j+3]=alpha*255;}
 finishHistory(before){const tiles=[];let bytes=0;for(const[key,b]of before){const after=this.tile(key);if(b.data.some((v,i)=>v!==after.data[i])){tiles.push({before:b,after});bytes+=b.data.byteLength+after.data.byteLength;}}if(tiles.length)this.undoStack.push({tiles,bytes});while(this.historyBytes>ART_HISTORY_BYTES||this.historyCount>40)this.undoStack.shift();}
 end(){if(!this.active)return false;const before=this.active.before;for(const b of before.values())for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++){const i=(y*W+x)*4;if(this.mask[i/4])this.mix(i,this.ink);}this.active=null;this.mask.fill(0);this.finishHistory(before);this.changed();return true;}
 applyTiles(action,which){for(const p of action.tiles){const t=p[which];for(let j=0;j<t.h;j++)this.ink.set(t.data.subarray(j*t.w*4,(j+1)*t.w*4),((t.y+j)*W+t.x)*4);}}
 undo(){this.end();const a=this.undoStack.pop();if(!a)return false;this.applyTiles(a,'before');this.redoStack.push(a);this.changed();return true;}
 redo(){this.end();const a=this.redoStack.pop();if(!a)return false;this.applyTiles(a,'after');this.undoStack.push(a);this.changed();return true;}
 replace(data,{restored=false,paperColor=this.paperColor}={}){if(!(data instanceof Uint8ClampedArray)||data.length!==W*H*4)throw Error('Invalid artwork pixels');this.end();const before=new Map();if(!restored)for(let y=0;y<H;y+=T)for(let x=0;x<W;x+=T){const key=y/T*12+x/T;before.set(key,this.tile(key));}this.ink.set(data);this.paperColor=/^#[0-9a-f]{6}$/i.test(paperColor)?paperColor:'#fff7df';this.redoStack=[];if(restored)this.undoStack=[];else this.finishHistory(before);this.changed();}
 clear(){this.replace(new Uint8ClampedArray(W*H*4));}
 reset(){this.active=null;this.ink.fill(0);this.mask.fill(0);this.undoStack=[];this.redoStack=[];this.paperColor='#fff7df';this.changed();}
 composite(){const paper=rgb(this.paperColor),out=this.output;for(let i=0;i<out.length;i+=4){this.mix(i,out);const a=out[i+3]/255;for(let k=0;k<3;k++)out[i+k]=Math.round(out[i+k]*a+paper[k]*(1-a));out[i+3]=255;}return out;}
}
